"""Write /case.html: the detail page of one case (every row of the search list has one; grouped rows show their series),
and /series.html, a redirect kept for old links.
The search list links each grouped row here (series.html?id=<row id>); the page asks api.cgi?id=… for that row.
Called from udb.py build with the page pieces it already has, so it looks and behaves like the search page."""
import re, sys
from pathlib import Path
H = Path(__file__).resolve().parent
sys.path.insert(0, str(H))
import sidemenu

def js_functions(js, names):
    """Copy named 'function f(...){...}' definitions out of the search page script (brace-matched)."""
    out = []
    for n in names:
        i = js.index(f'function {n}(')
        d, j = 0, js.index('{', i)
        while True:
            d += {'{': 1, '}': -1}.get(js[j], 0); j += 1
            if d == 0: break
        out.append(js[i:j])
    return ''.join(out)

